-- Social identity and immutable completion contributions; no gameplay rewards.
CREATE TABLE factions(id TEXT PRIMARY KEY,name TEXT NOT NULL,name_key TEXT NOT NULL UNIQUE,tag TEXT NOT NULL UNIQUE,description TEXT NOT NULL,logo_json TEXT NOT NULL,owner_id TEXT NOT NULL REFERENCES users(id),join_policy TEXT NOT NULL CHECK(join_policy IN ('open','apply','invite')),version INTEGER NOT NULL DEFAULT 1,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,disbanded_at INTEGER);
CREATE TABLE faction_members(faction_id TEXT NOT NULL REFERENCES factions(id),user_id TEXT PRIMARY KEY REFERENCES users(id),role TEXT NOT NULL CHECK(role IN ('Owner','Officer','Member')),joined_at INTEGER NOT NULL);
CREATE UNIQUE INDEX faction_one_owner ON faction_members(faction_id) WHERE role='Owner';
CREATE TABLE faction_invites(id TEXT PRIMARY KEY,faction_id TEXT NOT NULL REFERENCES factions(id),sender_id TEXT NOT NULL REFERENCES users(id),recipient_id TEXT NOT NULL REFERENCES users(id),state TEXT NOT NULL DEFAULT 'pending' CHECK(state IN ('pending','accepted','declined','cancelled','blocked','expired')),expires_at INTEGER NOT NULL,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL);
CREATE UNIQUE INDEX faction_one_invite ON faction_invites(faction_id,recipient_id) WHERE state='pending';
CREATE TABLE faction_applications(id TEXT PRIMARY KEY,faction_id TEXT NOT NULL REFERENCES factions(id),user_id TEXT NOT NULL REFERENCES users(id),state TEXT NOT NULL DEFAULT 'pending' CHECK(state IN ('pending','accepted','declined','cancelled')),created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL);
CREATE UNIQUE INDEX faction_one_application ON faction_applications(faction_id,user_id) WHERE state='pending';
CREATE TABLE faction_privacy(user_id TEXT PRIMARY KEY REFERENCES users(id),allow_invites INTEGER NOT NULL DEFAULT 1 CHECK(allow_invites IN (0,1)),updated_at INTEGER NOT NULL);
CREATE TABLE faction_blocks(user_id TEXT NOT NULL REFERENCES users(id),faction_id TEXT NOT NULL REFERENCES factions(id),created_at INTEGER NOT NULL,PRIMARY KEY(user_id,faction_id));
CREATE TABLE faction_confirmations(token_hash TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),faction_id TEXT NOT NULL REFERENCES factions(id),action TEXT NOT NULL CHECK(action IN ('transfer','disband')),target_id TEXT REFERENCES users(id),version INTEGER NOT NULL,expires_at INTEGER NOT NULL,used_at INTEGER);
CREATE TABLE faction_requests(user_id TEXT NOT NULL REFERENCES users(id),request_id TEXT NOT NULL,action TEXT NOT NULL,payload_hash TEXT NOT NULL,response_json TEXT NOT NULL,created_at INTEGER NOT NULL,PRIMARY KEY(user_id,request_id));
CREATE TABLE faction_activity(id INTEGER PRIMARY KEY AUTOINCREMENT,faction_id TEXT NOT NULL REFERENCES factions(id),type TEXT NOT NULL,actor_id TEXT REFERENCES users(id),actor_name TEXT,subject_id TEXT REFERENCES users(id),subject_name TEXT,details_json TEXT NOT NULL,created_at INTEGER NOT NULL);
CREATE INDEX faction_activity_recent ON faction_activity(faction_id,id DESC);
CREATE TABLE faction_match_activity(match_id TEXT NOT NULL,user_id TEXT NOT NULL REFERENCES users(id),faction_id TEXT NOT NULL REFERENCES factions(id),faction_name TEXT NOT NULL,faction_tag TEXT NOT NULL,mode TEXT NOT NULL,queue TEXT NOT NULL,revision TEXT NOT NULL,stats_json TEXT NOT NULL,completed_at INTEGER NOT NULL,PRIMARY KEY(match_id,user_id));
CREATE INDEX faction_match_activity_by_faction ON faction_match_activity(faction_id,completed_at);
CREATE TABLE faction_reports(id TEXT PRIMARY KEY,reporter_id TEXT NOT NULL REFERENCES users(id),faction_id TEXT NOT NULL REFERENCES factions(id),category TEXT NOT NULL CHECK(category IN ('faction','name-logo')),reason TEXT NOT NULL,snapshot_json TEXT NOT NULL,state TEXT NOT NULL DEFAULT 'pending',created_at INTEGER NOT NULL);
CREATE TRIGGER faction_activity_no_update BEFORE UPDATE ON faction_activity BEGIN SELECT RAISE(ABORT,'Faction activity is immutable'); END;
CREATE TRIGGER faction_activity_no_delete BEFORE DELETE ON faction_activity BEGIN SELECT RAISE(ABORT,'Faction activity is immutable'); END;
CREATE TRIGGER faction_match_activity_no_update BEFORE UPDATE ON faction_match_activity BEGIN SELECT RAISE(ABORT,'Faction match activity is immutable'); END;
CREATE TRIGGER faction_match_activity_no_delete BEFORE DELETE ON faction_match_activity BEGIN SELECT RAISE(ABORT,'Faction match activity is immutable'); END;
